              "name": "Task-3 Sonar reader.txt",
              "content": "int trigPin = 10;\nint echoPin = 9;\n\nlong duration;\nfloat distance;\n\nvoid setup() {\n  pinMode(trigPin, OUTPUT); // Sound made by trigger pin will be sent out\n  pinMode(echoPin, INPUT); // Signal will be recieved by Echo pin\n  Serial.begin(9600); // Data rate \n}\n\nvoid loop() {\n  digitalWrite(trigPin, LOW);\n  delayMicroseconds(2); // Initially keeping clear by turning off \n  digitalWrite(trigPin, HIGH);\n  delayMicroseconds(10); // Keeping high for sending sound waves\n  digitalWrite(trigPin, LOW); // Turning off\n\n  while (digitalRead(echoPin) == LOW); \n  long startTime = micros(); // Starting count down in microsec\n\n  while (digitalRead(echoPin) == HIGH); \n  long endTime = micros(); // Stopping count down\n\n  duration = endTime - startTime;\n  distance = duration * 0.034 / 2;\n\n  Serial.print(\"Distance: \");\n  Serial.println(distance);\n  Serial.println(\" cm\");\n\n  delay(100); // Gap between taking each reading \n}"
